const recentTokenOps = std.timestamp({}).then(invoke => std.timeadd({
    duration: invoke.result,
    timestamp: "-24h",
})).then(invoke => hcloudplus.getActivities({
    includeUserActivities: false,
    types: [
        "token.create",
        "token.delete",
    ],
    createdAfter: invoke.result,
}));
export const recentTokenEvents = recentTokenOps.then(recentTokenOps => recentTokenOps.activities);
